package authz

// RouteRule binds exact registered endpoints to permissions. Unlisted endpoints
// are denied. Native registrations stay intact; coverage checks this table against the real router.
type RouteRule struct {
	All, Any                                 []string
	ReadOnly                                 bool
	RequestSchema                            string
	SuperOnly, Self, Mutates, NewCredentials bool
}

func (r RouteRule) Allows(s Subject) bool {
	if s.Role == SuperAdmin {
		return true
	}
	if s.Role != Admin || r.SuperOnly {
		return false
	}
	if r.Self {
		return true
	}
	if len(r.All) == 0 && len(r.Any) == 0 {
		return false
	}
	if !s.CanAll(r.All...) {
		return false
	}
	return len(r.Any) == 0 || s.CanAny(r.Any...)
}

