func RuleFor(method, path string) (RouteRule, bool) {
	rule, ok := routeRules[method+" "+path]
	return rule, ok
}
func DeclaredRoutes() map[string]RouteRule {
	out := make(map[string]RouteRule, len(routeRules))
	for key, value := range routeRules {
		out[key] = value
	}
	return out
}
